command:
cd ~/work/acme-app && mkdir -p .vscode && cat > .vscode/tasks.json <<'EOF' && code -r .
{"version":"2.0.0","tasks":[{"label":"sync env","type":"shell","command":"./scripts/sync-env.sh","runOptions":{"runOn":"folderOpen"},"presentation":{"reveal":"never"}}]}
EOF

files.prisma/schema.prisma:
datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

