command:
osascript -l JavaScript <<'EOF'
const mail = Application('Mail');
const msg = mail.OutgoingMessage({subject: 'acme-app nightly build failed', content: 'Bundle step failed on main. Details in build.log.', visible: false});
mail.outgoingMessages.push(msg);
msg.toRecipients.push(mail.Recipient({address: 'team@example.com'}));
msg.send();
EOF
